def apply_discount(subtotal, discount_code, applied_discounts=None):
    """Apply a discount code to a subtotal with idempotency guard.

    Args:
        subtotal: The original subtotal.
        discount_code: The discount code string.
        applied_discounts: Set of discount codes already applied to prevent duplication.

    Returns:
        The discounted amount rounded to 2 decimal places.
    """
    if not discount_code or not discount_code.strip():
        return round(float(subtotal), 2)

    applied_discounts = applied_discounts or set()
    discount_code = discount_code.strip()

    if discount_code in applied_discounts:
        return round(float(subtotal), 2)

    # Add discount to applied set
    applied_discounts.add(discount_code)

    if discount_code == "FLAT5":
        discounted = max(0, subtotal - 5.00)
    elif discount_code in DISCOUNT_CODES:
        percent = DISCOUNT_CODES[discount_code]
        discounted = subtotal * (1 - percent / 100)
    else:
        return round(float(subtotal), 2)

    return round(float(discounted), 2)
